const input = $input.first().json;
const component = /^[A-Za-z0-9._-]+$/;
const defaultModels = { openai: 'gpt-5', anthropic: 'claude-sonnet-4-20250514', google: 'models/gemini-2.5-pro' };
if (input.outcome_code !== 'SEMANTIC_EXECUTION_FAILED') throw new Error('Diagnosis requires SEMANTIC_EXECUTION_FAILED');
if (typeof input.run_id !== 'string' || !component.test(input.run_id)) throw new Error('run_id must be one safe path component');
if (!Number.isInteger(input.execution_attempt) || input.execution_attempt < 1) throw new Error('execution_attempt must be a positive integer');
if (!['openai', 'anthropic', 'google'].includes(input.diagnosis_provider)) throw new Error('diagnosis_provider must be openai, anthropic, or google');
if (input.model !== undefined && (typeof input.model !== 'string' || !input.model.trim())) throw new Error('model must be a non-empty string when supplied');
if (typeof input.failure_report_path !== 'string') throw new Error('failure_report_path is required');
const reportPath = input.failure_report_path.replace(/\\/g, '/');
const runPrefix = `artifacts/work/runs/${input.run_id}/`;
if (!reportPath.startsWith(runPrefix) || reportPath.includes('..') || reportPath.includes(',')) throw new Error('failure_report_path must identify this run under artifacts/work');
return [{ json: {
  run_id: input.run_id, execution_attempt: input.execution_attempt, provider: input.diagnosis_provider,
  model: typeof input.model === 'string' ? input.model.trim() : defaultModels[input.diagnosis_provider],
  failure_report_path: `/data/artifacts/${reportPath.slice('artifacts/work/'.length)}`,
  evidence_ref: reportPath.slice(runPrefix.length),
  system_prompt_path: '/data/diagnosis_prompts/semantic_failure_diagnosis.md'
} }];

const context = $('Validate Input').first().json;
let report;
try { report = JSON.parse($input.first().json.failure_report_text); } catch (error) { throw new Error(`Invalid failure report JSON: ${error.message}`); }
if (report.report_type !== 'semantic_test_case_failure') throw new Error('Unexpected failure report type');
if (report.identity.run_id !== context.run_id || report.identity.attempt !== context.execution_attempt) throw new Error('Failure report identity does not match the requested run and attempt');
if (report.test_case_result.syntax_check.status !== 'passed' || report.test_case_result.semantic_status !== 'failed') throw new Error('Diagnosis requires parser passed and semantic test failed');
if (report.source_diagnosis.eligible !== true || report.source_diagnosis.reason !== 'parser_passed_and_semantic_test_failed') throw new Error('Failure report is not eligible for source diagnosis');
const bundle = report.source_diagnosis.evidence_bundle;
if (!bundle || Array.isArray(bundle) || typeof bundle !== 'object') throw new Error('Failure report has no evidence bundle');
const required = ['original_task_description', 'relevant_source_and_target_metamodel_constraints', 'generated_transformation', 'failing_test_case_or_assertion', 'input_model', 'expected_output_or_properties', 'actual_target_model', 'structured_actual_vs_expected_difference', 'generated_execution_summary', 'reference_transformation_result'];
// Presence, not an exact key set. The report carries further evidence than a
// diagnosis reads - changes, syntax_status, stack_traces, maven_log_excerpt -
// and Source Diagnosis must not stop working because the report grew a field.
// Tested with `in` rather than truthiness: an assertion failure legitimately
// carries an empty stack_traces array and a null maven_log_excerpt.
const missing = required.filter((field) => !(field in bundle));
if (missing.length > 0) throw new Error(`Evidence bundle is missing: ${missing.join(', ')}`);
const failing = bundle.failing_test_case_or_assertion;
if (typeof failing.test_case_id !== 'string' || !failing.test_case_id || typeof failing.assertion_id !== 'string' || !failing.assertion_id) throw new Error('Evidence bundle must identify one test case and assertion');
if (failing.test_case_id !== report.test_case_result.test_case_id || failing.assertion_id !== report.test_case_result.assertion_id) throw new Error('Evidence bundle selectors disagree with the failure report');
const difference = bundle.structured_actual_vs_expected_difference;
const differenceFields = ['missing_elements', 'extra_elements', 'wrong_types', 'wrong_attributes', 'reference_mismatches'];
// The object stays mandatory, but an unavailable difference is a legitimate
// shape: no comparator produces the model-level diff yet, so requiring it
// would reject every real report. What must not happen is a diff that claims
// to be available while carrying nothing, so the fields are checked only then.
if (!difference || typeof difference !== 'object' || Array.isArray(difference)) throw new Error('Evidence bundle requires a structured actual-vs-expected difference object');
if (typeof difference.available !== 'boolean') throw new Error('The structured actual-vs-expected difference must state whether it is available');
if (difference.available === true && differenceFields.some((field) => !Array.isArray(difference[field]))) throw new Error('An available structured actual-vs-expected difference must be complete');
return [{ json: { ...context, test_case_id: failing.test_case_id, assertion_id: failing.assertion_id, evidence_bundle: bundle } }];

const context = $('Validate Evidence Bundle').first().json;
const systemPrompt = $input.first().json.system_prompt;
if (typeof systemPrompt !== 'string' || !systemPrompt.trim()) throw new Error('Diagnosis prompt is empty');
return [{ json: { ...context, system_prompt: systemPrompt.trim(), user_prompt: JSON.stringify(context.evidence_bundle, null, 2) } }];

const context = $('Assemble Diagnosis Bundle').first().json;
const executionId = String($execution.id).replace(/[^A-Za-z0-9._-]+/g, '-');
const executionAttempt = String(context.execution_attempt).padStart(3, '0');
const artifactDirectory = `/data/artifacts/runs/${context.run_id}/responses/source-diagnosis/execution-attempt-${executionAttempt}/n8n-execution-${executionId}`;
const request = {
  schema_version: '1.0',
  run_id: context.run_id,
  execution_attempt: context.execution_attempt,
  provider: context.provider,
  model: context.model,
  temperature: 0,
  test_case_id: context.test_case_id,
  assertion_id: context.assertion_id,
  evidence_ref: context.evidence_ref,
  messages: [
    { role: 'system', content: context.system_prompt },
    { role: 'user', content: context.user_prompt },
  ],
};
// Every artifact path this diagnosis writes is derived here, once. The write
// nodes read them back by name: a Convert to File node hands on binary data
// with an empty json, so a path rebuilt from $json downstream would resolve
// its run id and attempt to undefined and miss the directory just created.
return [{ json: {
  ...context,
  artifact_directory: artifactDirectory,
  request_path: `${artifactDirectory}/diagnosis_request.json`,
  raw_response_path: `${artifactDirectory}/diagnosis_raw_response.txt`,
  result_path: `${artifactDirectory}/diagnosis_result.json`,
  n8n_execution_id: executionId,
  diagnosis_request_text: JSON.stringify(request, null, 2),
} }];

const source = $input.first().json;
const context = $('Build Diagnosis Request Artifact').first().json;
const rawResponseText = typeof source.text === 'string' ? source.text : JSON.stringify(source, null, 2);
return [{ json: {
  ...context,
  llm_response: source,
  diagnosis_raw_response_text: rawResponseText,
} }];

const captured = $('Capture Raw Diagnosis Response').first().json;
const source = captured.llm_response;
const context = $('Build Diagnosis Request Artifact').first().json;
if (typeof source.text !== 'string' || !source.text.trim()) throw new Error('Diagnosis LLM returned no text');
let parsed;
try { parsed = JSON.parse(source.text.trim()); } catch (error) { throw new Error(`Diagnosis LLM returned invalid JSON: ${error.message}`); }
if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('Diagnosis response must be one JSON object');
const required = ['classification', 'confidence', 'reasoning_summary', 'evidence', 'test_case_id', 'assertion_id'];
if (JSON.stringify(Object.keys(parsed).sort()) !== JSON.stringify([...required].sort())) throw new Error(`Diagnosis response must contain exactly: ${required.join(', ')}`);
if (parsed.test_case_id !== context.test_case_id) throw new Error('Diagnosis test_case_id does not match the failing case');
if (parsed.assertion_id !== context.assertion_id) throw new Error('Diagnosis assertion_id does not match the failing assertion');
if (!['transformation_defect', 'test_defect', 'ambiguous'].includes(parsed.classification)) throw new Error('Invalid diagnosis classification');
if (!['low', 'medium', 'high'].includes(parsed.confidence)) throw new Error('Invalid diagnosis confidence');
if (typeof parsed.reasoning_summary !== 'string' || !parsed.reasoning_summary.trim() || parsed.reasoning_summary.length > 1000) throw new Error('reasoning_summary must be 1-1000 characters');
if (!Array.isArray(parsed.evidence) || parsed.evidence.length < 1 || parsed.evidence.length > 8 || parsed.evidence.some((entry) => typeof entry !== 'string' || !entry.trim() || entry.length > 1000)) throw new Error('evidence must contain 1-8 concise strings');
const persistedClassification = { transformation_defect: 'TRANSFORMATION_DEFECT', test_defect: 'TEST_DEFECT', ambiguous: 'AMBIGUOUS' }[parsed.classification];
const evidence = parsed.evidence.map((entry) => entry.trim());
const createdAt = new Date().toISOString();
const rationale = `${parsed.reasoning_summary.trim()} Evidence: ${evidence.join(' | ')}`;
const diagnosisResult = {
  schema_version: '1.0',
  run_id: context.run_id,
  execution_attempt: context.execution_attempt,
  classification: parsed.classification,
  persisted_classification: persistedClassification,
  confidence: parsed.confidence,
  reasoning_summary: parsed.reasoning_summary.trim(),
  evidence,
  test_case_id: parsed.test_case_id,
  assertion_id: parsed.assertion_id,
  evidence_ref: context.evidence_ref,
  provider: context.provider,
  model: context.model,
  created_at: createdAt,
};
return [{ json: {
  ...diagnosisResult,
  artifact_directory: context.artifact_directory,
  n8n_execution_id: context.n8n_execution_id,
  rationale,
  diagnosis_result_text: JSON.stringify(diagnosisResult, null, 2),
} }];
